def MDHTrans(alpha, a, d, theta):
    """返回改进DH参数的齐次变换矩阵"""
    return sp.Matrix([
        [cos(theta), -sin(theta), 0, a],
        [sin(theta)*cos(alpha), cos(theta)*cos(alpha), -sin(alpha), -d*sin(alpha)],
        [sin(theta)*sin(alpha), cos(theta)*sin(alpha), cos(alpha), d*cos(alpha)],
        [0, 0, 0, 1]
    ])

def motion_para_clc(axis, R_inv, Po, dq, ddq, Pc, w_pre, v_pre, dw_pre, dv_pre):
    w = simplify(R_inv @ w_pre + dq * axis)
    # print(f"w = {w}")
    v = simplify(R_inv @ (v_pre + w_pre.cross(Po)))
    # print(f"v = {v}")
    dw = simplify(R_inv @ dw_pre + (R_inv @ w_pre).cross(dq * axis) + ddq * axis)
    # print(f"dw = {dw}")
    dv = simplify(R_inv @ (dv_pre + dw_pre.cross(Po) + w_pre.cross(w_pre.cross(Po))))
    # print(f"dv = {dv}")
    dvc = simplify(dv + dw.cross(Pc) + w.cross(w.cross(Pc)))
    # print(f"dvc = {dvc}")
    return w, v, dw, dv, dvc

def fn_clc(R, Po, w, dw, dv, dvc, m, Pc, I, f_next, n_next):
    f = R @ f_next + m * dvc
    n = R @ n_next + Po.cross(R @ f_next) + I @ dw + w.cross(I @ w) + m * Pc.cross(dv)
    return f, n

